def solve(gi):
    from collections import Counter
    H=len(gi);W=len(gi[0])
    bg=Counter(v for r in gi for v in r).most_common(1)[0][0]
    best=None
    for y in range(H):
        for x in range(W):
            if gi[y][x]!=bg and not (best and (y,x) in set(best[0])):
                st=[(y,x)];cells={(y,x)};seen={y:x};col=gi[y][x]
                key=lambda s:(len(s['cells']),)
                pass
    # redo cleanly
    seen=[[False]*W for _ in range(H)]
    def comp(y,x):
        st=[(y,x)];cells={(y,x)};seen[y][x]=True;col=gi[y][x]
        while st:
            yy,xx=st.pop()
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    ny,nx=yy+dy,xx+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and gi[ny][nx]==col:
                        seen[ny][nx]=True;st.append((ny,nx));cells.add((ny,nx))
        return col,sorted(cells)
    for y in range(H):
        for x in range(W):
            if gi[y][x]!=bg and not seen[y][x]:
                c,cells=comp(y,x)
                ys=[p[0] for p in cells];xs=[p[1] for p in cells]
                h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
                key=(len(cells),w,h,y)
                if best is None or key>best[0]:
                    best=(key,c,len(cells))
    _,c,n=best
    return [[c]]*n
